SELECT id, plan, monthly_fee, customer_id, status, end_date, LAST_VALUE(customer_id) OVER (PARTITION BY plan ORDER BY monthly_fee, id ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS last_customer_id, ROUND(AVG(monthly_fee) OVER (PARTITION BY status, plan ORDER BY end_date, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW), 2) AS monthly_fee_moving_avg_4 FROM subscriptions WHERE plan = 'basic';
